def article(slug, title, excerpt, category, tags, image, content):
    words = len(re.sub('<[^>]+>', ' ', content).split())
    return {
        'slug': slug, 'title': title, 'excerpt': excerpt, 'category': category,
        'tags': tags, 'content': content, 'author': 'Disque Amizade',
        'date': '2026-08-22', 'readTime': max(6, round(words / 155)),
        'image': image, 'coverImage': image, 'wordCount': words,
        'lastModified': '2026-08-22', 'relatedSlugs': []
    }

