data = json.loads(INDEX.read_text())
existing = {p['slug'] for p in data}
duplicates = [a['slug'] for a in articles if a['slug'] in existing]
if duplicates:
    raise SystemExit(f'Duplicate slug detected; refusing to append: {duplicates}')
data.extend(articles)
INDEX.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n')
print(f'appended {len(articles)} articles; total {len(data)}; words {[a["wordCount"] for a in articles]}')
